import{_ as r,o as a,c as o,a2 as e}from"./chunks/framework.CRFziyHp.js";const n="/images/placeholder-ai-scenario-routes.svg",l="/images/placeholder-ai-platform-admin.svg",b=JSON.parse('{"title":"AI 中台","description":"灵萌 AI 中台配置指南：大模型供应商接入、场景路由、配额管理与智能评论等 AI 能力开启说明。","frontmatter":{"title":"AI 中台","description":"灵萌 AI 中台配置指南：大模型供应商接入、场景路由、配额管理与智能评论等 AI 能力开启说明。"},"headers":[],"relativePath":"features/ai.md","filePath":"features/ai.md","lastUpdated":1785018026000}'),s={name:"features/ai.md"};function i(d,t,h,g,u,p){return a(),o("div",null,[...t[0]||(t[0]=[e('<h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>统一管理大模型供应商、模型、场景路由与配额，为官方机器人 AI 回复、智能评论等能力提供底层 AI 服务。</p><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>AI 中台模块已在授权中开通（侧栏 <strong>AI中台</strong> 可见）。</li><li>已在各模型供应商处开通 API 并获取密钥。</li><li>账号具备 AI 中台相关读写权限。</li></ul><h2 id="管理后台配置步骤" tabindex="-1">管理后台配置步骤 <a class="header-anchor" href="#管理后台配置步骤" aria-label="Permalink to &quot;管理后台配置步骤&quot;">​</a></h2><p>建议 <strong>严格按以下顺序</strong> 配置，否则场景无法调用模型：</p><h3 id="第一步-供应商管理" tabindex="-1">第一步：供应商管理 <a class="header-anchor" href="#第一步-供应商管理" aria-label="Permalink to &quot;第一步：供应商管理&quot;">​</a></h3><p>路径：<strong>AI中台 → 供应商管理</strong></p><ul><li>新增供应商（OpenAI 兼容、国内大模型等，以页面支持列表为准）</li><li>填写 API Key、Base URL（如有）、默认参数</li><li>保存后可测试连通（若页面提供测试按钮）</li></ul><h3 id="第二步-模型管理" tabindex="-1">第二步：模型管理 <a class="header-anchor" href="#第二步-模型管理" aria-label="Permalink to &quot;第二步：模型管理&quot;">​</a></h3><p>路径：<strong>AI中台 → 模型管理</strong></p><ul><li>在已添加的供应商下注册 <strong>模型 ID</strong>（与供应商控制台名称一致）</li><li>设置上下文长度、默认温度等</li></ul><h3 id="第三步-场景路由" tabindex="-1">第三步：场景路由 <a class="header-anchor" href="#第三步-场景路由" aria-label="Permalink to &quot;第三步：场景路由&quot;">​</a></h3><p>路径：<strong>AI中台 → 场景路由</strong></p><ul><li>为每个 <strong>业务场景</strong>（如官方机器人对话、智能评论、通知 AI 文案等）指定使用的 <strong>模型</strong></li><li>可配置 fallback 模型、超时策略（以页面为准）</li></ul><p><img src="'+n+'" alt="场景路由示意"></p><h3 id="其他常用菜单" tabindex="-1">其他常用菜单 <a class="header-anchor" href="#其他常用菜单" aria-label="Permalink to &quot;其他常用菜单&quot;">​</a></h3><table tabindex="0"><thead><tr><th>菜单</th><th>作用</th></tr></thead><tbody><tr><td><strong>中控台概览</strong></td><td>总览用量与健康</td></tr><tr><td><strong>Prompt 模板</strong></td><td>各场景系统提示词</td></tr><tr><td><strong>配额规则</strong></td><td>按用户 / 区域限流</td></tr><tr><td><strong>用量与日志</strong></td><td>排查调用失败</td></tr><tr><td><strong>风险审核</strong></td><td>敏感内容拦截记录</td></tr><tr><td><strong>AI 对话</strong></td><td>管理员在线测试模型</td></tr></tbody></table><h3 id="与业务功能的关联" tabindex="-1">与业务功能的关联 <a class="header-anchor" href="#与业务功能的关联" aria-label="Permalink to &quot;与业务功能的关联&quot;">​</a></h3><table tabindex="0"><thead><tr><th>业务</th><th>关联方式</th></tr></thead><tbody><tr><td><strong>官方机器人 AI 回复</strong></td><td><a href="/features/bot-notify">官方机器人</a> 编辑配置中开启 AI → 依赖场景路由中机器人场景</td></tr><tr><td><strong>智能评论</strong></td><td><strong>评论运营 → 智能评论配置 / 智能评论机器人 / 计划与任务</strong></td></tr><tr><td><strong>通知 AI 文案</strong></td><td><strong>通知控制台 → AI 文案</strong></td></tr></tbody></table><h2 id="区域配置" tabindex="-1">区域配置 <a class="header-anchor" href="#区域配置" aria-label="Permalink to &quot;区域配置&quot;">​</a></h2><p>AI 供应商与模型为 <strong>全站共用</strong>。配额规则、部分 Prompt 可按区域或用户等级区分（在 <strong>配额规则</strong> 中配置）。</p><p>官方机器人、智能评论仍按 <strong>区域</strong> 启用，但共用同一套模型路由。</p><h2 id="验证是否生效" tabindex="-1">验证是否生效 <a class="header-anchor" href="#验证是否生效" aria-label="Permalink to &quot;验证是否生效&quot;">​</a></h2><ol><li>完成供应商 → 模型 → 场景路由三步。</li><li>打开 <strong>AI中台 → AI 对话</strong>，选择刚配置的模型发送测试问题，能正常回复。</li><li>在 <strong>官方机器人</strong> 或 <strong>智能评论</strong> 中开启 AI，客户端触发一次，<strong>用量与日志</strong> 中有记录且无连续失败。</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>场景路由保存后仍报「无可用模型」</strong></p><ul><li>模型 ID 与供应商控制台不一致。</li><li>供应商 Key 失效或余额不足。</li></ul><p><strong>侧栏没有 AI中台</strong></p><ul><li>模块未开通：到 <strong>系统设置 → 我的模块</strong> 查看 AI 中台是否已解锁；或当前账号未被分配 AI 中台菜单权限。</li></ul><p><strong>回复内容违规或为空</strong></p><ul><li>查看 <strong>风险审核</strong> 是否拦截；调整 <strong>Prompt 模板</strong> 或供应商审核策略。</li></ul><p><strong>官方机器人与智能评论共用 Key 吗</strong></p><ul><li>共用 <strong>供应商 / 模型 / 场景路由</strong> 基础设施，但场景名不同，可在 <strong>场景路由</strong> 中为它们指定不同模型。</li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/features/bot-notify">官方机器人</a></li><li><a href="/features/notification">通知与推送</a></li></ul><p><img src="'+l+'" alt="AI 中台控制台示意"></p>',37)])])}const I=r(s,[["render",i]]);export{b as __pageData,I as default};
